from speech_client import AzureSpeechClient
import os

def select_voice(locale=None, config=None):
    config = config or {}
    subscription_key = config.get('api_key', os.environ.get('AZURE_SPEECH_KEY'))
    region = config.get('region', os.environ.get('AZURE_SPEECH_REGION'))

    client = AzureSpeechClient(subscription_key, region)
    available_voices = client.list_voices()

    if locale:
        filtered_voices = [voice for voice in available_voices if voice['locale'].lower() == locale.lower()]
        return filtered_voices
    else:
        return available_voices

import os

def save_audio(audio_result, file_path):
    if not isinstance(audio_result.audio_data, bytes):
        raise TypeError("audio_result.audio_data must be bytes.")

    try:
        with open(file_path, 'wb') as audio_file:
            audio_file.write(audio_result.audio_data)
        return {"status": "success", "file_path": file_path}
    except IOError as e:
        raise RuntimeError(f"Failed to save audio to {file_path}: {e}")

from google.cloud import translate_v2 as translate
import os

def translate_script(text, target_language, project_id=None):
    if not project_id:
        project_id = os.environ.get('GOOGLE_CLOUD_PROJECT')

    translate_client = translate.Client(project=project_id)

    if isinstance(text, bytes):
        text = text.decode("utf-8")

    result = translate_client.translate(text, target_language=target_language)

    return {
        "translated_text": result["translatedText"],
        "source_language": result["detectedSourceLanguage"],
    }

from google.cloud import language_v2 as language
import os

def check_script_safety(text, project_id=None):
    if not project_id:
        project_id = os.environ.get('GOOGLE_CLOUD_PROJECT')

    client = language.LanguageServiceClient()

    document = language.Document(content=text, type_=language.Document.Type.PLAIN_TEXT)

    try:
        response = client.classify_text(document=document)
        safety_categories = []
        for category in response.categories:
            safety_categories.append({
                "name": category.name,
                "confidence": category.confidence
            })
        return {"safety_scores": safety_categories}
    except Exception as e:
        sentiment_response = client.analyze_sentiment(document=document)
        sentiment = sentiment_response.document_sentiment
        return {
            "sentiment_score": sentiment.score,
            "sentiment_magnitude": sentiment.magnitude,
            "message": "Classify text failed or not applicable, returned sentiment analysis as an indicator of safety."
        }

from google.cloud import aiplatform
import os

def embed_script(text, project_id=None, location='us-central1'):
    if not project_id:
        project_id = os.environ.get('GOOGLE_CLOUD_PROJECT')

    aiplatform.init(project=project_id, location=location)

    model = aiplatform.TextEmbeddingModel.from_pretrained("text-embedding-004")

    embeddings = model.get_embeddings([text])

    return {"embedding": embeddings[0].values}
